{"content":"#!/usr/bin/env node
// extract.js: extract 32-bit little/big-endian memory words from PT_LOAD segments.
// Usage: node extract.js /app/a.out > out.json
const fs = require('fs');

function readU16(buf, off, le) {
  return le ? buf.readUInt16LE(off) : buf.readUInt16BE(off);
}
function readU32(buf, off, le) {
  return le ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
}
function readU64(buf, off, le) {
  // returns Number (safe for typical virtual addresses < 2^53)
  const lo = le ? buf.readUInt32LE(off) : buf.readUInt32BE(off + 4);
  const hi = le ? buf.readUInt32LE(off + 4) : buf.readUInt32BE(off);
  return hi * 0x100000000 + lo;
}

function main() {
  const path = process.argv[2];
  if (!path) {
    console.error('Usage: node extract.js <binary>');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);
  if (buf.length < 64 || buf[0] !== 0x7f || buf[1] !== 0x45 || buf[2] !== 0x4c || buf[3] !== 0x46) {
    console.error('Not an ELF file');
    process.exit(1);
  }
  const eiClass = buf[4]; // 1 = 32-bit, 2 = 64-bit
  const eiData = buf[5];  // 1 = LE, 2 = BE
  const le = eiData === 1;
  const is64 = eiClass === 2;

  let e_phoff, e_phentsize, e_phnum;
  if (is64) {
    e_phoff = Number(readU64(buf, 0x20, le));
    e_phentsize = readU16(buf, 0x36, le);
    e_phnum = readU16(buf, 0x38, le);
  } else {
    e_phoff = readU32(buf, 0x1c, le);
    e_phentsize = readU16(buf, 0x2a, le);
    e_phnum = readU16(buf, 0x2c, le);
  }

  const out = {};
  for (let i = 0; i < e_phnum; i++) {
    const h = e_phoff + i * e_phentsize;
    if (h + e_phentsize > buf.length) break;
    let p_type, p_offset, p_vaddr, p_filesz;
    if (is64) {
      p_type = readU32(buf, h, le);
      // p_flags at h+4 (unused)
      p_offset = Number(readU64(buf, h + 8, le));
      p_vaddr = Number(readU64(buf, h + 16, le));
      // p_paddr at h+24 (unused)
      p_filesz = Number(readU64(buf, h + 32, le));
      // p_memsz at h+40 (BSS excluded: only file-backed bytes are dumped)
    } else {
      p_type = readU32(buf, h, le);
      p_offset = readU32(buf, h + 4, le);
      p_vaddr = readU32(buf, h + 8, le);
      // p_paddr at h+12
      p_filesz = readU32(buf, h + 16, le);
    }
    const PT_LOAD = 1;
    if (p_type !== PT_LOAD) continue;
    // Only full 4-byte words; ignore trailing 1-3 bytes.
    for (let off = 0; off + 4 <= p_filesz; off += 4) {
      const fo = p_offset + off;
      if (fo + 4 > buf.length) break;
      const val = readU32(buf, fo, le);
      const va = p_vaddr + off;
      out[String(va)] = val;
    }
  }
  process.stdout.write(JSON.stringify(out));
}

main();
